INSERT INTO "packages" VALUES(1,1,'Pakaian Dasar','Essential Look','Rp 899k','Untuk brand yang baru melangkah ke dunia digital.','For brands taking their first step into the digital fashion space.','["1 template pilihan","5 halaman utama","Personalisasi dasar","Responsif semua perangkat","1x revisi","Dukungan 30 hari"]','["1 chosen template","5 key pages","Basic branding","Fully responsive across devices","1 revision round","30-day post-launch support"]',0,'2026-09-18 11:54:47','2026-09-18 11:54:47');
INSERT INTO "packages" VALUES(2,2,'Koleksi Lengkap','Full Collection','Rp 1.899k','Keseimbangan terbaik untuk brand yang sedang tumbuh.','The sweet spot for fashion labels ready to expand their reach.','["2 template pilihan","10 halaman + blog","Personalisasi penuh","SEO dasar","Micro-interaction halus","3x revisi + dukungan 3 bulan"]','["2 template options","10 pages + journal \/ lookbook","Full brand personalization","Foundational fashion SEO","Smooth editorial micro-interactions","3 revision rounds + 90-day support"]',1,'2026-09-18 11:54:47','2026-09-18 11:54:47');
INSERT INTO "packages" VALUES(3,3,'Boutique Eksklusif','Haute Couture','Rp 3.499k','Pengalaman penuh untuk brand fashion yang serius.','A bespoke runway experience for established fashion houses.','["Template premium pilihan","Halaman tanpa batas","Integrasi katalog & pesanan","SEO lengkap","Revisi tanpa batas (2 bulan)","Dukungan 12 bulan + pelatihan"]','["Premium flagship template","Unlimited pages & categories","Catalog & direct order integration","Comprehensive fashion SEO suite","Unlimited revisions (60 days)","12-month priority support & handover training"]',0,'2026-09-18 11:54:47','2026-09-18 11:54:47');
